import unittest

class Test(unittest.TestCase):
    def test_succeeds_after_retries(self):
        state = {'count': 0}
        @retry(max_attempts=3, should_retry=lambda e: True)
        def flaky():
            state['count'] += 1
            if state['count'] < 3:
                raise ValueError('fail')
            return 'ok'
        self.assertEqual(flaky(), 'ok')
        self.assertEqual(state['count'], 3)
    def test_exhausts_attempts_and_raises(self):
        @retry(max_attempts=2, should_retry=lambda e: True)
        def always_fails():
            raise ValueError('nope')
        with self.assertRaises(ValueError):
            always_fails()
    def test_should_retry_false_stops_immediately(self):
        state = {'count': 0}
        @retry(max_attempts=5, should_retry=lambda e: False)
        def fails_once():
            state['count'] += 1
            raise ValueError('nope')
        with self.assertRaises(ValueError):
            fails_once()
        self.assertEqual(state['count'], 1)

if __name__ == '__main__':
    unittest.main()
